      "mainEntity": [
        {
          "@type": "Question",
          "name": "What standards guide your electronics recycling services?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS uses documented handling procedures that can support NIST 800-88 media sanitization planning, HIPAA privacy reviews, and California electronic waste requirements. Project records may include pickup details, asset information, processing documentation, and certificates requested during the engagement. These records give procurement, facilities, and information security teams a practical basis for reviewing equipment disposition."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield, Kern County, and organizations across the Central Valley through scheduled commercial pickup. Service planning can include offices, campuses, warehouses, healthcare sites, agricultural operations, and public-sector facilities based on volume and access requirements. Organizations searching for electronics recycling near me throughout Bakersfield can request coverage details for Kern County locations."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup timing depends on equipment volume, site access, transportation planning, and the requested service scope. Contact STS with your location, equipment categories, and preferred schedule to discuss same-week availability and a practical collection plan."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to equipment after pickup?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is received, sorted, and documented according to the project scope. Data-bearing devices can receive secure processing, while reusable components and recyclable materials are directed through appropriate downstream channels with reporting available for the organization. This process helps organizations separate data security requirements from material recovery and equipment reuse decisions."
          }
        }
